                        for (let i = 0; i < count; i++) {
                            try {
                                const netObj = netObjListRaw.method("get_Item").invoke(i);
                                if (!netObj || netObj.isNull()) continue;
                                try {
                                    const hasPC = netObj.method("GetComponent", 1).inflate(PCClass).invoke();
                                    if (hasPC && !hasPC.isNull()) continue;
                                } catch(_) {}
                                const go = netObj.method("get_gameObject").invoke();
                                if (!go || go.isNull()) continue;
                                const name = go.method("get_name").invoke()?.content ?? ("NetObj_" + i);
                                teleportNetObjList.push({ obj: go, name });
                            } catch(_) {}
                        }
                        teleportNetObjIndex = 0;
                        const cur = teleportNetObjList.length > 0 ? teleportNetObjList[0].name : "none";
                        sendNotification("Teleport list: " + teleportNetObjList.length + " objects. Current: " + cur, false, 5);
