                        console.log("[UX] Rot    : " + rot);
                        console.log("[UX] Scale  : " + scl);
                        console.log("[UX] Components (" + comps.length + "): " + comps.join(", "));
                        console.log("[UX] ═══════════════════════════════");
                        sendNotification(uxSelectedName + " | " + pos + " | " + comps.length + " comps — see log", false, 6);
