                                let clipName = "none";
                                try { const c = s.method("get_clip").invoke(); if (c && !c.isNull()) clipName = c.method("get_name").invoke()?.content ?? "?"; } catch(_) {}
                                const vol = (s.method("get_volume").invoke() as number).toFixed(2);
